create table if not exists public.prescriptions (id uuid primary key default gen_random_uuid(),patient_id uuid not null references public.profiles(id) on delete restrict,doctor_id uuid not null references public.profiles(id) on delete restrict,diagnosis text,clinical_notes text,status text not null default 'active' check(status in('active','completed','cancelled')),prescribed_at timestamptz not null default timezone('utc',now()),updated_at timestamptz not null default timezone('utc',now()));
create table if not exists public.prescription_medications (id uuid primary key default gen_random_uuid(),prescription_id uuid not null references public.prescriptions(id) on delete cascade,medicine_name text not null check(length(trim(medicine_name)) between 1 and 160),medicine_form text not null check(medicine_form in('tablet','capsule','syrup','injection','cream','drops','inhaler','other')),strength text,dosage text not null,frequency text not null,duration text not null,quantity text,instructions text,created_at timestamptz not null default timezone('utc',now()));
create index if not exists prescriptions_patient_date_idx on public.prescriptions(patient_id,prescribed_at desc); create index if not exists prescriptions_doctor_date_idx on public.prescriptions(doctor_id,prescribed_at desc); create index if not exists prescription_medications_parent_idx on public.prescription_medications(prescription_id);
drop trigger if exists prescriptions_set_updated_at on public.prescriptions; create trigger prescriptions_set_updated_at before update on public.prescriptions for each row execute function public.set_updated_at();
alter table public.prescriptions enable row level security; alter table public.prescription_medications enable row level security;
create policy "prescriptions_select_patient_or_author" on public.prescriptions for select to authenticated using(patient_id=(select auth.uid()) or doctor_id=(select auth.uid()));
create policy "prescriptions_insert_verified_care_doctor" on public.prescriptions for insert to authenticated with check(doctor_id=(select auth.uid()) and (select private.is_verified_doctor((select auth.uid()))) and exists(select 1 from public.conversations c where c.patient_id=prescriptions.patient_id and c.doctor_id=(select auth.uid())));
create policy "prescriptions_update_author" on public.prescriptions for update to authenticated using(doctor_id=(select auth.uid())) with check(doctor_id=(select auth.uid()) and exists(select 1 from public.conversations c where c.patient_id=prescriptions.patient_id and c.doctor_id=(select auth.uid())));
create policy "medications_select_prescription_participants" on public.prescription_medications for select to authenticated using(exists(select 1 from public.prescriptions p where p.id=prescription_id and(p.patient_id=(select auth.uid()) or p.doctor_id=(select auth.uid()))));
create policy "medications_insert_prescribing_doctor" on public.prescription_medications for insert to authenticated with check(exists(select 1 from public.prescriptions p where p.id=prescription_id and p.doctor_id=(select auth.uid())));
create policy "medications_update_prescribing_doctor" on public.prescription_medications for update to authenticated using(exists(select 1 from public.prescriptions p where p.id=prescription_id and p.doctor_id=(select auth.uid()))) with check(exists(select 1 from public.prescriptions p where p.id=prescription_id and p.doctor_id=(select auth.uid())));
grant select,insert on public.prescriptions to authenticated; grant update(status,diagnosis,clinical_notes) on public.prescriptions to authenticated; grant select,insert on public.prescription_medications to authenticated; grant update(medicine_name,medicine_form,strength,dosage,frequency,duration,quantity,instructions) on public.prescription_medications to authenticated;
create or replace function public.create_prescription(target_patient uuid,diagnosis_text text,notes_text text,medications jsonb) returns uuid language plpgsql security invoker set search_path=public,pg_temp as $$ declare new_id uuid;item jsonb;begin if jsonb_typeof(medications)<>'array' or jsonb_array_length(medications)=0 then raise exception 'At least one medication is required';end if;insert into public.prescriptions(patient_id,doctor_id,diagnosis,clinical_notes) values(target_patient,(select auth.uid()),nullif(trim(diagnosis_text),''),nullif(trim(notes_text),'')) returning id into new_id;for item in select * from jsonb_array_elements(medications) loop insert into public.prescription_medications(prescription_id,medicine_name,medicine_form,strength,dosage,frequency,duration,quantity,instructions) values(new_id,trim(item->>'medicine_name'),item->>'medicine_form',nullif(trim(item->>'strength'),''),trim(item->>'dosage'),trim(item->>'frequency'),trim(item->>'duration'),nullif(trim(item->>'quantity'),''),nullif(trim(item->>'instructions'),''));end loop;return new_id;end $$;
revoke all on function public.create_prescription(uuid,text,text,jsonb) from public,anon; grant execute on function public.create_prescription(uuid,text,text,jsonb) to authenticated;
